#define RU_PRESET_ASSIGN_COUNT ((uint8_t)(sizeof(ru_preset_targets)/sizeof(ru_preset_targets[0])))
#define RU_PRESET_GROUP_COUNT ((uint8_t)(sizeof(ru_preset_groups)/sizeof(ru_preset_groups[0])))
static inline uint8_t ru_preset_assign_valid(uint8_t id){return id<RU_PRESET_ASSIGN_COUNT;}
static inline uint8_t ru_preset_group_first(uint8_t group){
 for(uint8_t i=0u;i<RU_PRESET_ASSIGN_COUNT;i++)if(ru_preset_targets[i].group==group)return i;
 return RU_PRESET_ASSIGN_DEFAULT;
}
static inline uint8_t ru_preset_group_last(uint8_t group){
 /* Exclusive upper bound, for safe scrolling across each category. */
 for(uint8_t i=RU_PRESET_ASSIGN_COUNT;i>0u;i--)if(ru_preset_targets[i-1u].group==group)return i;
 return RU_PRESET_ASSIGN_DEFAULT;
}
